seq-sum:
: sum-helper
  (forall ρ; ρ xs:Seq Int^many total:Int^many idx:Int^many -- ρ total:Int^many)
  locals { xs total idx } {
    idx xs prim seq-int.len prim <
    [
      [ xs idx prim seq-int.at total prim + idx 1 prim + xs ] call
      swap swap
      sum-helper
    ]
    [ total ]
    if
  };

: main
  (forall ρ; ρ xs:Seq Int^many -- ρ total:Int^many)
  xs 0 0 sum-helper
  ;

